// Get data from webhook
const fullLogRaw = $('Webhook').first().json.body.full_log;
const data = $('Webhook').first().json.body;

// =============================================
// STEP 1: Replace literal \r\n with actual line breaks
// =============================================
const cleanLog = fullLogRaw.replace(/\\r\\n/g, '\n');

// =============================================
// STEP 2: Remove the JSON garbage after the event
// =============================================
const jsonStartIndex = cleanLog.indexOf('"},"eventdata":');
let finalLog = cleanLog;
if (jsonStartIndex !== -1) {
  finalLog = cleanLog.substring(0, jsonStartIndex);
}

// =============================================
// STEP 3: Extract values using simple regex on clean lines
// =============================================

// Extract Username
let username = "unknown";
const usernameMatch = finalLog.match(/Account Name:\s*(\S+)/);
if (usernameMatch) username = usernameMatch[1];

// Extract Domain
let domain = "unknown";
const domainMatch = finalLog.match(/Account Domain:\s*(\S+)/);
if (domainMatch) domain = domainMatch[1];

// Extract Group Name
let group = "unknown";
const groupMatch = finalLog.match(/Group Name:\s*(.+?)(?:\n|$)/);
if (groupMatch) group = groupMatch[1].trim();

// Extract Subject SID
let subjectSid = "unknown";
const subjectSidMatch = finalLog.match(/Security ID:\s*(\S+)/);
if (subjectSidMatch) subjectSid = subjectSidMatch[1];

// Extract Target SID
let targetSid = "unknown";
const targetSidMatch = finalLog.match(/Target SID:\s*(\S+)/);
if (targetSidMatch) {
  targetSid = targetSidMatch[1];
} else {
  // Fallback to JSON extraction
  const jsonMatch = fullLogRaw.match(/"targetSid":"([^"]+)"/);
  if (jsonMatch) targetSid = jsonMatch[1];
}

// Extract Logon ID
let logonId = "unknown";
const logonIdMatch = finalLog.match(/Logon ID:\s*(\S+)/);
if (logonIdMatch) logonId = logonIdMatch[1];

// Extract Computer
let computer = "unknown";
const computerMatch = finalLog.match(/computer:\s*(\S+)/i);
if (computerMatch) computer = computerMatch[1];

// Extract Event ID
let eventId = "4799";
const eventIdMatch = finalLog.match(/Event ID:\s*(\d+)/i);
if (eventIdMatch) eventId = eventIdMatch[1];

// IP to Computer mapping
const agentIp = data.agent_ip || "";
const ipToComputerMap = {
  "192.168.77.10": "PGHMNG",
  "192.168.20.4": "MARIA$",
  "192.168.20.5": "JOHN$"
};
if (computer === "unknown" && agentIp) {
  computer = ipToComputerMap[agentIp] || agentIp;
}

// =============================================
// DEBUG - Check extracted values
// =============================================
console.log("=== CLEAN EXTRACTED VALUES ===");
console.log("Username:", username);
console.log("Domain:", domain);
console.log("Group:", group);
console.log("Subject SID:", subjectSid);
console.log("Target SID:", targetSid);
console.log("Computer:", computer);
console.log("Logon ID:", logonId);
console.log("==============================");

// =============================================
// TASKS
// =============================================
const tasks = [
  {
    title: "Pre/Post Activities Collection",
    description: "Collecting same user activities from Wazuh"
  },
  {
    title: "Emulator threat actor instant blocking",
    description: " Block $input.first().json.body.enumerator_name 's VM via ip "
  },
  {
    title: "Report Generation",
    description: "Generate incident report from collected data"
  }
];

// =============================================
// OBSERVABLES
// =============================================
const observables = [
  {
    dataType: "ip",
    data: agentIp || "unknown",
    message: "Source Agent IP Address",
    tlp: 2
  },
  {
    dataType: "hostname",
    data: computer,
    message: "Computer Name",
    tlp: 2
  },
  {
    dataType: "user",
    data: username,
    message: "User Account",
    tlp: 2
  },
  {
    dataType: "other",
    data: group,
    message: "Group Enumerated",
    tlp: 2
  },
  {
    dataType: "other",
    data: subjectSid,
    message: "Subject SID",
    tlp: 2
  },
  {
    dataType: "other",
    data: targetSid,
    message: "Target SID",
    tlp: 2
  }
];

// =============================================
// SHARING PARAMETERS
// =============================================
const sharingParameters = [
  {
    key: "tlp",
    value: "AMBER",
    organisation: "PGHSOC"
  },
  {
    key: "pap",
    value: "AMBER",
    organisation: "PGHSOC"
  },
  {
    key: "tags",
    value: ["Enumeration", "AD Enumeration", "EventID_4799"],
    organisation: "PGHSOC"
  }
];

// =============================================
// CLEAN CASE DESCRIPTION - Using extracted values only
// =============================================
const timestamp = new Date().toISOString();

const caseDescription = `## Incident Summary

A security-enabled local group membership enumeration was detected (Event ID ${eventId}).

---

## Event Details

| Field | Value |
|-------|-------|
| Detection Time | ${timestamp} |
| Computer | ${computer} |
| Source IP | ${agentIp || "unknown"} |
| User | ${username} |
| Domain | ${domain} |
| Logon ID | ${logonId} |
| Group Enumerated | ${group} |
| Severity | HIGH |
| Rule ID | 110401 |

---

## Security Identifiers (SIDs)

| Field | Value |
|-------|-------|
| Subject SID | ${subjectSid} |
| Target SID | ${targetSid} |

---

## What Happened

User ${username} from domain ${domain} enumerated the ${group} group on computer ${computer} (${agentIp}).

This activity indicates reconnaissance behavior that often precedes lateral movement or privilege escalation attacks.

---

## Recommended Actions

| Priority | Action |
|----------|--------|
| High | Investigate user ${username} for additional suspicious activities |
| High | Review authentication logs for ${username} |
| Medium | Check for recent privilege escalations |
| Medium | Correlate with other AD enumeration alerts |

---

*Automatically created by n8n incident response workflow*`;

// =============================================
// OUTPUT
// =============================================
return [{
  json: {
    title: `AD Enumeration - ${username} enumerated ${group} on ${computer}`,
    tags: ["Enumeration", "AD Enumeration", "EventID_4799"],
    description: caseDescription,
    severity: 2,
    tasks: tasks,
    observables: observables,
    sharingParameters: sharingParameters
  }
