// =============================================
// CODE NODE 1: Generate Prompt for DeepSeek - SUMMARIZE RESULTS
// =============================================

// Get data from your existing nodes
let wazuhAlerts = [];
let webhookData = {};

try {
  // Handle different possible structures from Alerts_Content_Ext
  const alertsContent = $('Deduplication').first().json;

  // Check if it's already an array
  if (Array.isArray(alertsContent)) {
    wazuhAlerts = alertsContent;
  }
  // Check if it has a 'hits' array
  else if (alertsContent.hits && Array.isArray(alertsContent.hits)) {
    wazuhAlerts = alertsContent.hits;
  }
  // Check if it has a 'hits.hits' structure (Elasticsearch format)
  else if (alertsContent.hits && alertsContent.hits.hits && Array.isArray(alertsContent.hits.hits)) {
    wazuhAlerts = alertsContent.hits.hits;
  }
  // Check if it has a 'data' array
  else if (alertsContent.data && Array.isArray(alertsContent.data)) {
    wazuhAlerts = alertsContent.data;
  }
  // Check if it has an 'alerts' array
  else if (alertsContent.alerts && Array.isArray(alertsContent.alerts)) {
    wazuhAlerts = alertsContent.alerts;
  }
  // If none of the above, try to convert object values to array
  else if (typeof alertsContent === 'object' && alertsContent !== null) {
    wazuhAlerts = Object.values(alertsContent).filter(v => Array.isArray(v))[0] || [];
  }

  // Ensure it's an array
  if (!Array.isArray(wazuhAlerts)) {
    wazuhAlerts = [];
  }

} catch(e) {
  console.log("Error getting alerts:", e.message);
  wazuhAlerts = [];
}

try {
  webhookData = $('Webhook').first().json.body || {};
} catch(e) {
  webhookData = {};
}

const fullLogRaw = webhookData.full_log || "";

// =============================================
// CLEAN AND EXTRACT DATA
// =============================================
let cleanFullLog = fullLogRaw.replace(/\\r\\n/g, ' ');
cleanFullLog = cleanFullLog.replace(/\\t/g, ' ');
cleanFullLog = cleanFullLog.split('"},"eventdata":')[0];

// Extract key values
let username = "unknown";
const usernameMatch = cleanFullLog.match(/Account Name:\s*(\S+)/);
if (usernameMatch) username = usernameMatch[1];

let group = "unknown";
const groupMatch = cleanFullLog.match(/Group Name:\s*([^\s]+(?:\s+[^\s]+)*?)(?=\s+Group Domain:|$)/);
if (groupMatch) group = groupMatch[1].trim();

let computer = "unknown";
const computerMatch = cleanFullLog.match(/computer:\s*(\S+)/i);
if (computerMatch) computer = computerMatch[1];

let domain = "unknown";
const domainMatch = cleanFullLog.match(/Account Domain:\s*(\S+)/);
if (domainMatch) domain = domainMatch[1];

const agentIp = webhookData.agent_ip || webhookData.src_ip || "unknown";

// =============================================
// EXTRACT FROM WAZUH ALERTS (SAFE LOOP)
// =============================================
const commands = [];
const descriptions = [];
const timestamps = [];
const levels = [];

// Safely iterate over wazuhAlerts
if (Array.isArray(wazuhAlerts) && wazuhAlerts.length > 0) {
  for (const alert of wazuhAlerts) {
    try {
      // Handle different alert structures
      let source = {};

      if (alert._source) {
        source = alert._source;
      } else if (alert.source) {
        source = alert.source;
      } else {
        source = alert;
      }

      const content = alert.content || alert.full_log || source.full_log || JSON.stringify(source);

      // Extract command from exe field
      const exeMatch = content.match(/exe="([^"]+)"/);
      if (exeMatch) {
        const cmd = exeMatch[1].split('/').pop();
        if (cmd && !commands.includes(cmd)) commands.push(cmd);
      }

      // Extract description
      const desc = source.rule?.description || source.description || source.rule_description;
      if (desc && !descriptions.includes(desc)) descriptions.push(desc);

      // Extract timestamp
      if (source.timestamp) timestamps.push(source.timestamp);

      // Extract level
      const level = source.rule?.level || source.level;
      if (level) levels.push(parseInt(level));

    } catch(e) {
      console.log("Error processing alert:", e.message);
    }
  }
}

const uniqueCommands = [...new Set(commands)].slice(0, 15);
const uniqueDescriptions = [...new Set(descriptions)].slice(0, 20);
const avgLevel = levels.length > 0 ? (levels.reduce((a,b) => a + b, 0) / levels.length).toFixed(1) : "N/A";
const timeRange = timestamps.length > 1 ? `${timestamps[0]} to ${timestamps[timestamps.length-1]}` : timestamps[0] || "Single timestamp";

// =============================================
// FALLBACK DESCRIPTIONS IF NONE FOUND
// =============================================
let finalDescriptions = uniqueDescriptions;
if (finalDescriptions.length === 0 && group !== "unknown") {
  finalDescriptions = [`User ${username} enumerated the ${group} group on ${computer}`];
}

// =============================================
// BUILD PROMPT FOR DEEPSEEK - SUMMARIZATION
// =============================================
const promptSummary = `You are a cybersecurity incident analyst. Summarize the following security alerts.

## INCIDENT CONTEXT

| Field | Value |
|-------|-------|
| User | ${username} |
| Target Group | ${group} |
| Computer | ${computer} |
| Domain | ${domain} |
| Source IP | ${agentIp} |
| Total Alerts | ${wazuhAlerts.length} |
| Time Range | ${timeRange} |
| Average Alert Level | ${avgLevel} |

## ALERT DESCRIPTIONS

${finalDescriptions.map((d, i) => `${i+1}. ${d}`).join('\n') || "No descriptions available"}

## COMMANDS EXECUTED

${uniqueCommands.map((c, i) => `${i+1}. ${c}`).join('\n') || "No commands detected"}

## TASK

Provide a comprehensive SUMMARY with these sections:

### 1. EXECUTIVE SUMMARY
(3-4 sentences explaining what happened, who did it, when, and what the risk is)

### 2. KEY FINDINGS
- Most critical alerts
- Attack timeline
- Suspicious patterns detected

### 3. ATTACKER BEHAVIOR
- What techniques were used
- What phase of the kill chain
- What was the likely objective

### 4. RISK ASSESSMENT
- Risk level (Critical/High/Medium/Low)
- Impact if attack succeeds
- Current containment status

### 5. CONFIDENCE SCORE
(0-100% with reasoning)

Keep the response concise, professional, and actionable.`;

// =============================================
// DEBUG OUTPUT (remove in production)
// =============================================
console.log("=== DEBUG INFO ===");
console.log("wazuhAlerts type:", typeof wazuhAlerts);
console.log("Is array:", Array.isArray(wazuhAlerts));
console.log("Alerts count:", wazuhAlerts.length);
console.log("Descriptions found:", finalDescriptions.length);
console.log("Commands found:", uniqueCommands.length);
console.log("=================");

// =============================================
// OUTPUT
// =============================================
return [{
  json: {
    prompt: promptSummary,
    model: "deepseek-r1:7b",
    temperature: 0.3,
    max_tokens: 2000,
    node_type: "summarize_results",
    // Also pass metadata for debugging
    debug_info: {
      alerts_count: wazuhAlerts.length,
      descriptions_count: finalDescriptions.length,
      commands_count: uniqueCommands.length,
      avg_level: avgLevel
    }
  }
}];

