// CODE NODE 4: Generate Complete Incident Report
// WITH PROPER VARIABLE EXTRACTION
// =============================================

// =============================================
// STEP 1: COLLECT RESULTS FROM ALL 3 DEEPSEEK NODES
// =============================================

let summaryAnalysis = "Analysis not available";
let logAnalysis = "Analysis not available";
let mitigationAnalysis = "Analysis not available";

try {
  const summaryResponse = $('DeepSeek_Summarize').first().json.response;
  if (summaryResponse) summaryAnalysis = summaryResponse;
} catch(e) {}

try {
  const logResponse = $('DeepSeek_Log_Analysis').first().json.response;
  if (logResponse) logAnalysis = logResponse;
} catch(e) {}

try {
  const mitigationResponse = $('DeepSeek_Mitigations').first().json.response;
  if (mitigationResponse) mitigationAnalysis = mitigationResponse;
} catch(e) {}

// =============================================
// STEP 2: CLEAN THE AI RESPONSES
// =============================================

function cleanAIResponse(response) {
  if (typeof response !== 'string') {
    response = JSON.stringify(response);
  }
  response = response.replace(/[\s\S]*?/g, '');
  response = response.replace(/```html\n?/g, '');
  response = response.replace(/```json\n?/g, '');
  response = response.replace(/```\n?/g, '');
  response = response.replace(/Alright,[\s\S]*?(?=##|###|\n\n|$)/, '');
  return response.trim();
}

const cleanSummary = cleanAIResponse(summaryAnalysis);
let cleanLogAnalysis = cleanAIResponse(logAnalysis);
const cleanMitigation = cleanAIResponse(mitigationAnalysis);

// =============================================
// STEP 3: PARSE THE TABLE FROM LOG ANALYSIS
// =============================================

function parseMarkdownTable(markdown) {
  const lines = markdown.split('\n');
  const tableLines = [];
  let inTable = false;

  for (const line of lines) {
    if (line.trim().startsWith('|') && line.includes('|')) {
      inTable = true;
      tableLines.push(line);
    } else if (inTable && line.trim() === '') {
      break;
    } else if (inTable && !line.trim().startsWith('|')) {
      if (line.trim().length > 0) break;
    }
  }

  if (tableLines.length < 3) return null;

  const headers = tableLines[0].split('|').filter(cell => cell.trim()).map(cell => cell.trim());
  const rows = [];
  for (let i = 2; i < tableLines.length; i++) {
    const cells = tableLines[i].split('|').filter(cell => cell.trim());
    if (cells.length >= headers.length) {
      rows.push(cells.map(cell => cell.trim()));
    }
  }

  return { headers, rows };
}

function extractSection(content, sectionName) {
  const regex = new RegExp(`### ${sectionName}[\\s\\S]*?(?=###|$)`, 'i');
  const match = content.match(regex);
  return match ? match[0] : null;
}

const logTableData = parseMarkdownTable(cleanLogAnalysis);
const nextAttackSection = extractSection(cleanLogAnalysis, 'PART B: NEXT ATTACK PREDICTION');
const detectionGapsSection = extractSection(cleanLogAnalysis, 'PART C: DETECTION GAPS');

// =============================================
// STEP 4: EXTRACT RISK SCORE & CONFIDENCE SCORE
// =============================================

function extractScore(text, pattern) {
  const regex = new RegExp(pattern, 'i');
  const match = text.match(regex);
  if (match) {
    const numMatch = match[1].match(/\d+(?:\.\d+)?/);
    if (numMatch) return parseFloat(numMatch[0]);
  }
  return null;
}

let riskScore = null;
const riskPatterns = [
  /risk (?:level|score|rating)[:\s]*(\d+(?:\.\d+)?(?:\/10)?)/i,
  /risk[:\s]*(\d+(?:\.\d+)?)/i,
  /severity[:\s]*(\d+(?:\.\d+)?(?:\/10)?)/i
];

for (const pattern of riskPatterns) {
  riskScore = extractScore(cleanSummary, pattern);
  if (riskScore) break;
}

if (!riskScore) {
  const summaryLower = cleanSummary.toLowerCase();
  if (summaryLower.includes("critical")) riskScore = 9.5;
  else if (summaryLower.includes("high")) riskScore = 8.0;
  else if (summaryLower.includes("medium")) riskScore = 5.5;
  else if (summaryLower.includes("low")) riskScore = 2.5;
  else riskScore = 5.0;
}

let confidenceScore = null;
const confidencePatterns = [
  /confidence(?:\s+score)?[:\s]*(\d+(?:\.\d+)?)%/i,
  /confidence[:\s]*(\d+(?:\.\d+)?)/i
];

for (const pattern of confidencePatterns) {
  confidenceScore = extractScore(cleanSummary, pattern);
  if (confidenceScore) break;
}

if (!confidenceScore) confidenceScore = 75;

// =============================================
// STEP 5: DETERMINE RISK LEVEL
// =============================================
let riskLevel = "Medium";
if (riskScore >= 8.5) riskLevel = "Critical";
else if (riskScore >= 7.0) riskLevel = "High";
else if (riskScore >= 4.0) riskLevel = "Medium";
else riskLevel = "Low";

let verdict = "Suspicious";
if (cleanSummary.toLowerCase().includes("malicious")) verdict = "Malicious";
else if (cleanSummary.toLowerCase().includes("suspicious")) verdict = "Suspicious";

// =============================================
// STEP 6: GET ORIGINAL DATA - FIXED: Extract ALL webhook values FIRST
// =============================================

