cleanFullLog = cleanFullLog.replace(/\\t/g, ' ');
cleanFullLog = cleanFullLog.split('"},"eventdata":')[0];

let username = "unknown";
const usernameMatch = cleanFullLog.match(/Account Name:\s*(\S+)/);
if (usernameMatch) username = usernameMatch[1];
if (username === "unknown" && enumeratorName !== "unknown") username = enumeratorName;

let group = "unknown";
const groupMatch = cleanFullLog.match(/Group Name:\s*([^\s]+(?:\s+[^\s]+)*?)(?=\s+Group Domain:|$)/);
if (groupMatch) group = groupMatch[1].trim();

let computer = "unknown";
const computerMatch = cleanFullLog.match(/computer:\s*(\S+)/i);
if (computerMatch) computer = computerMatch[1];
if (computer === "unknown" && agentName !== "unknown") computer = agentName;

let domain = "unknown";
const domainMatch = cleanFullLog.match(/Account Domain:\s*(\S+)/);
if (domainMatch) domain = domainMatch[1];

let subjectSid = "unknown";
const subjectSidMatch = cleanFullLog.match(/Security ID:\s*(\S+)/);
if (subjectSidMatch) subjectSid = subjectSidMatch[1];

let targetSid = "unknown";
const targetSidMatch = cleanFullLog.match(/Target SID:\s*(\S+)/);
if (targetSidMatch) targetSid = targetSidMatch[1];

// Get alerts count
try {
