// MITRE Techniques
const techniques = [];
if (cleanLogAnalysis.toLowerCase().includes("bloodhound")) techniques.push("T1087 - Account Discovery");
if (cleanLogAnalysis.toLowerCase().includes("netstat")) techniques.push("T1046 - Network Service Scanning");
