// =============================================
// CODE NODE: Deduplicate Wazuh Alerts
// Removes alerts with identical: agent.name, agent.ip, rule.description, 
// rule.mitre, rule.id, rule.level, data.srcip
// Keeps only the most recent timestamp per unique combination
// =============================================

const wazuhResponse = $input.first().json;

// Extract alerts from response (handles different structures)
let alerts = [];
if (wazuhResponse.hits?.hits) {
  alerts = wazuhResponse.hits.hits;
} else if (Array.isArray(wazuhResponse)) {
  alerts = wazuhResponse;
} else if (wazuhResponse.data?.hits) {
  alerts = wazuhResponse.data.hits;
} else {
  alerts = [];
}

// =============================================
// STEP 1: Create unique key for each alert based on your fields
// =============================================
const uniqueAlerts = new Map(); // Key -> alert (keeps latest)

for (const alert of alerts) {
  const source = alert._source || alert;

  // Extract the fields you care about
  const agentName = source.agent?.name || source.agent_name || "";
  const agentIp = source.agent?.ip || source.agent_ip || "";
  const ruleDescription = source.rule?.description || source.description || "";
  const ruleMitre = source.rule?.mitre || source.mitre || "";
  const ruleId = source.rule?.id || source.rule_id || "";
  const ruleLevel = source.rule?.level || source.level || "";
  const timestamp = source.timestamp || alert.timestamp || "";
  const srcIp = source.data?.srcip || source.src_ip || "";

  // Create a unique key from all fields (empty values become empty strings)
  const uniqueKey = `${agentName}|${agentIp}|${ruleDescription}|${JSON.stringify(ruleMitre)}|${ruleId}|${ruleLevel}|${srcIp}`;

  // Check if we already have this combination
  if (!uniqueAlerts.has(uniqueKey)) {
    // Store the alert with its timestamp
    uniqueAlerts.set(uniqueKey, {
      agent: { name: agentName, ip: agentIp },
      rule: {
        description: ruleDescription,
        mitre: ruleMitre,
        id: ruleId,
        level: ruleLevel
      },
      src_ip: srcIp,
      timestamp: timestamp,
      original_alert: source
    });
  } else {
    // If duplicate, keep the one with newer timestamp
    const existing = uniqueAlerts.get(uniqueKey);
    if (new Date(timestamp) > new Date(existing.timestamp)) {
      uniqueAlerts.set(uniqueKey, {
        agent: { name: agentName, ip: agentIp },
        rule: {
          description: ruleDescription,
          mitre: ruleMitre,
          id: ruleId,
          level: ruleLevel
        },
        src_ip: srcIp,
        timestamp: timestamp,
        original_alert: source
      });
    }
  }
}

// =============================================
// STEP 2: Convert Map to array and sort by timestamp
// =============================================
const deduplicatedAlerts = Array.from(uniqueAlerts.values());

// Sort by timestamp (newest first)
deduplicatedAlerts.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

// =============================================
// STEP 3: Create clean output (without original_alert)
// =============================================
const cleanAlerts = deduplicatedAlerts.map(alert => ({
  agent: alert.agent,
  rule: alert.rule,
  src_ip: alert.src_ip,
  timestamp: alert.timestamp
}));

// =============================================
// STEP 4: Summary statistics
// =============================================
const summary = {
  total_raw_alerts: alerts.length,
  total_unique_alerts: cleanAlerts.length,
  duplicates_removed: alerts.length - cleanAlerts.length,
  deduplication_rate: ((alerts.length - cleanAlerts.length) / alerts.length * 100).toFixed(1) + "%",
  unique_rules: [...new Set(cleanAlerts.map(a => a.rule.id))],
  unique_agents: [...new Set(cleanAlerts.map(a => a.agent.name))],
  highest_level: Math.max(...cleanAlerts.map(a => parseInt(a.rule.level) || 0), 0)
};

// =============================================
// STEP 5: OUTPUT
// =============================================
return [{
  json: {
    // Clean deduplicated alerts - ready for DeepSeek
    alerts: cleanAlerts,

    // Summary statistics
    summary: summary,

    // For quick reference (text format)
    quick_view: cleanAlerts.map(a => 
      `[${a.rule.level}] ${a.rule.description} | ${a.agent.name} (${a.agent.ip}) | ${a.timestamp}`
    ).join('\n'),

    // For DeepSeek prompt generation
    deepseek_input: {
      total_alerts: cleanAlerts.length,
      alert_descriptions: cleanAlerts.map(a => a.rule.description),
      rule_ids: summary.unique_rules,
      agents: summary.unique_agents,
      highest_level: summary.highest_level,
      all_alerts: cleanAlerts
    }
  }
}];
